cuda_src = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

__global__ void matmul_fp16_kernel(const half* __restrict__ A,
                                   const half* __restrict__ B,
                                   half* __restrict__ C,
                                   int M, int N, int K) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;   // [0, M)
    int col = blockIdx.x * blockDim.x + threadIdx.x;   // [0, N)

    if (row < M && col < N) {
        float acc = 0.0f;
        // A is (M, K), B is (N, K). We need A[i,k] * B[j,k] summed over k.
        for (int k = 0; k < K; ++k) {
            half a = A[row * K + k];
            half b = B[col * K + k];   // B row = col (since B is N×K)
            acc += __half2float(a) * __half2float(b);
        }
        C[row * N + col] = __float2half(acc);
    }
}

torch::Tensor matmul_fp16(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kHalf && B.dtype() == torch::kHalf,
