        reinterpret_cast<const half*>(B.data_ptr()),
        reinterpret_cast<half*>(C.data_ptr()),
        static_cast<int>(M),
        static_cast<int>(N),
        static_cast<int>(K));

    cudaDeviceSynchronize();
    return C;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("matmul_fp16", &matmul_fp16, "FP16 matrix multiplication (A * Bᵀ)");
}
